//! Python `str.casefold`, exactly.
//!
//! Why: the registry stores `email.casefold()` and the handshake compares
//! against it (`pairing.py` `triple`, `service.py` `pair`). A fold that differs
//! from Python's on any code point would refuse a paired profile, or pair two
//! spellings Python keeps apart. Rust's `to_lowercase` is not case folding.
//! What: `casefold.tsv` is Python 3.12's full mapping (every code point whose
//! `casefold()` differs from itself), generated by
//! `tests/fixtures/capture/gen_casefold.py`; unmapped code points pass through.
//! Test: `casefold_matches_python_on_every_code_point`,
//! `casefold_hard_cases_match_python` in `tests/parity_casefold.rs`.

use std::collections::HashMap;
use std::sync::OnceLock;

const TABLE: &str = include_str!("casefold.tsv");

fn table() -> &'static HashMap<char, Vec<char>> {
    static MAP: OnceLock<HashMap<char, Vec<char>>> = OnceLock::new();
    MAP.get_or_init(|| {
        TABLE
            .lines()
            .filter(|l| !l.starts_with('#') && !l.is_empty())
            .filter_map(|line| {
                let (from, to) = line.split_once('\t')?;
                let from = char::from_u32(u32::from_str_radix(from, 16).ok()?)?;
                let to = to
                    .split(' ')
                    .map(|h| u32::from_str_radix(h, 16).ok().and_then(char::from_u32))
                    .collect::<Option<Vec<char>>>()?;
                Some((from, to))
            })
            .collect()
    })
}

/// `s.casefold()` as Python 3.12 computes it.
pub fn casefold(s: &str) -> String {
    let map = table();
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match map.get(&c) {
            Some(to) => out.extend(to.iter()),
            None => out.push(c),
        }
    }
    out
}

/// Number of mapped code points (a sanity check that the table parsed whole).
pub fn table_len() -> usize {
    table().len()
}

/// Python `str.isspace` for one character: Rust's `White_Space` plus U+001C..U+001F.
pub fn py_space(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// Python `s.strip()` with no argument.
pub fn py_strip(s: &str) -> &str {
    s.trim_matches(py_space)
}
